dataTableFormat:
{
  "is multi section": "true",
  "shared resource": {
    "phenotype map": "cfde phenotypes"
  },
  "sections": [
    {
      "section id": "pigean_gene_set",
      "header": "Connecting mouse and human phenotypes",
      "data point unused": {
        "type": "bioindex",
        "url": "https://cfde-dev.hugeampkpnbi.org/api/bio/",
        "index": "pigean-gene-set",
        "parameters": [
          "mousePhenotype"
        ],
        "parameters type": "array",
        "data type": "bioindex"
      },
      "data point": {
        "type": "bioindex",
        "url": "https://cfde-dev.hugeampkpnbi.org/api/bio/query/pigean-gene-set?q=$mousePhenotype1&limit=10000",
        "continue url": "https://cfde.hugeampkpnbi.org/api/bio/cont?limit=10000&token=",
        "parameters": [
          "mousePhenotype1"
        ],
        "parameters type": "replace or",
        "data type": "bioindex"
      },
      "search parameters": [
        {
          "parameter": "mousePhenotype1",
          "label": "Phenotype (mouse)",
          "type": "list",
          "values": "cfde mouse phenotypes"
        }
      ],
      "table format": {
        "data convert": [
          {
            "type": "map name",
            "field name": "Human phenotype",
            "raw field": "phenotype",
            "map": "shared resource",
            "map name": "phenotype map"
          },
          {
            "type": "raw",
            "field name": "raw phenotype",
            "raw field": "phenotype"
          },
          {
            "type": "raw",
            "field name": "Other mouse phenotypes associated with this human phenotype",
            "raw field": "phenotype"
          },
          {
            "type": "raw",
            "field name": "Group",
            "raw field": "trait_group"
          },
          {
            "type": "raw",
            "field name": "Gene sets",
            "raw field": "phenotype"
          },
          {
            "type": "phenotype probability",
            "field name": "Probability",
            "group": "trait_group",
            "rare": [
              "rare_v2"
            ],
            "common": [
              "gcat_trait",
              "portal"
            ],
            "beta": "beta_uncorrected"
          },
          {
            "type": "js math",
            "field name": "Fold-increase",
            "raw field": "beta_uncorrected",
            "method": "exp"
          },
          {
            "type": "raw",
            "field name": "Joint effect",
            "raw field": "beta",
            "if no value": "0"
          },
          {
            "type": "raw",
            "field name": "Marginal effect",
            "raw field": "beta_uncorrected",
            "if no value": "0"
          },
          {
            "type": "raw",
            "field name": "Number of gene sets",
            "raw field": "n"
          },
          {
            "type": "raw",
            "field name": "Study",
            "raw field": "study"
          },
          {
            "type": "raw",
            "field name": "Source",
            "raw field": "source"
          },
          {
            "type": "join multi",
            "field name": "Genes in gene set",
            "fields to join": [
              "phenotype",
              "gene_set"
            ],
            "join by": [
              ","
            ]
          },
          {
            "type": "replace characters",
            "field name": "Background",
            "raw field": "trait_group",
            "replace": [
              {
                "from": "rare_v2",
                "to": "0.005"
              },
              {
                "from": "gcat_trait",
                "to": "0.05"
              },
              {
                "from": "portal",
                "to": "0.05"
              }
            ]
          },
          {
            "type": "replace characters",
            "field name": "Background group",
            "raw field": "trait_group",
            "replace": [
              {
                "from": "rare_v2",
                "to": "rare"
              },
              {
                "from": "gcat_trait",
                "to": "common"
              },
              {
                "from": "portal",
                "to": "common"
              }
            ]
          },
          {
            "type": "raw",
            "field name": "Relative success score",
            "raw field": "rs_score"
          }
        ],
        "initial sort by": "Probability",
        "top rows": [
          "Human phenotype",
          "Group",
          "Probability",
          "Relative success score",
          "Fold-increase",
          "Joint effect",
          "Marginal effect",
          "Source",
          "Other mouse phenotypes associated with this human phenotype",
          "Genes in gene set"
        ],
        "tool tips": {
          "Human phenotype": "Human phenotypes associated with the queried mouse phenotype",
          "Other mouse phenotypes associated with this human phenotype": "Find additional mouse phenotypes that are genetically linked to the human phenotype in this row",
          "Probability": "Probability scores are obtained from the following equation: exp(marginal effect + log(background/(1-background))) / (1 + exp(marginal effect + log(background/(1-background)))), where background estimates are 0.05 for common phenotypes and  0.005 for rare phenotypes.",
          "Fold-increase": "Scores provided from the exponential value of the marginal effect",
          "Group": "Origin of the human phenotype in each row. Phenotype identifiers are from the Association to Function Knowledge Portal (portal), Orphanet (rare_v2), or the GWAS Catalog (gcat_trait). See the Searchable options page to map identifiers to descriptive terms.",
          "Joint effect": "The joint effect of a gene set measures its relevance to the phenotype when considered jointly across all gene sets in the model; this measure quantifies whether a gene set is maximally predictive of a phenotype compared to all other gene sets in the model. All gene set effects are expressed in units of log-odds of probabilities. Consider the following thresholds for interpreting joint gene set effects: >0.01 = significant, >0.1 = strongly significant, and >1.0 = among the strongest for any phenotype and any gene set. Genes with high marginal effects but weak joint effects are relevant to the phenotype in question but likely correlated with another gene set(s) that are more relevant to the phenotype.",
          "Marginal effect": "The marginal effect of a gene set measures its relevance to the phenotype when considered in isolation; this is the default measure by which the table is sorted and is the analog of traditional enrichment statistics. All gene set effects are expressed in units of log-odds of probabilities. Consider the following thresholds for interpreting marginal gene set effects: >0.01 = significant, >0.1 = strongly significant, and >1.0 = among the strongest for any phenotype and any gene set.",
          "Source": "Source of the gene set",
          "Genes in gene set": "View all genes in the gene set, sorted by relevance to the phenotype.",
          "Hypothesis": "Use GPT-4o to suggest how the 10 genes within this set most associated with the phenotype are related to the phenotype, using the gene set as context to the query. The subtable shows the response from GPT-4o as well as the input prompt, so that it can be copied into your favorite ChatBot to initiate further lines of inquiry."
        },
        "column formatting": {
          "Probability": {
            "type": [
              "scientific notation"
            ]
          },
          "Joint effect": {
            "type": [
              "scientific notation"
            ]
          },
          "Fold-increase": {
            "type": [
              "scientific notation"
            ]
          },
          "Other mouse phenotypes associated with this human phenotype": {
            "type": [
              "link"
            ],
            "link to": "/r/kc_phenotype_x_hs2mouse?phenotype=",
            "link type": "button",
            "link label": "Search"
          },
          "Source": {
            "type": [
              "kp phenotype link"
            ],
            "link to": "/r/kc_gene_set_browser_source?source="
          },
          "Genes in gene set": {
            "type": [
              "dynamic subsection"
            ],
            "label": "Show",
            "subsection": {
              "data point": {
                "type": "bioindex",
                "url": "https://cfde-dev.hugeampkpnbi.org/api/bio/",
                "index": "pigean-joined-gene-set",
                "parameters": [
                  "phenotype",
                  "mousePhenotype"
                ],
                "parameters type": "array",
                "data type": "bioindex"
              },
              "table format": {
                "data convert": [
                  {
                    "type": "raw",
                    "field name": "Gene",
                    "raw field": "gene"
                  },
                  {
                    "type": "raw",
                    "field name": "Model",
                    "raw field": "gene_set_size"
                  },
                  {
                    "type": "raw",
                    "field name": "Combined genetic support",
                    "raw field": "combined"
                  },
                  {
                    "type": "raw",
                    "field name": "Direct support (w/ gene sets)",
                    "raw field": "log_bf"
                  },
                  {
                    "type": "raw",
                    "field name": "Gene set evidence",
                    "raw field": "prior"
                  },
                  {
                    "type": "raw",
                    "field name": "Source",
                    "raw field": "source"
                  }
                ],
                "top rows": [
                  "Gene",
                  "Model",
                  "Combined genetic support",
                  "Direct support (w/ gene sets)",
                  "Gene set evidence"
                ],
                "column formatting": {
                  "Gene": {
                    "type": [
                      "link with parameters"
                    ],
                    "link to": "/r/kc_gene_set_browser_gene?",
                    "parameters": {
                      "gene": "Gene",
                      "model": "Model"
                    }
                  }
                }
              }
            }
          }
        }
      },
      "filters unused": [
        {
          "field": "Phenotype name",
          "label": "Phenotype",
          "type": "search",
          "features": [
            "autocomplete"
          ],
          "label in bubble": "true"
        },
        {
          "field": "Source",
          "label": "Source",
          "type": "checkbox",
          "label in bubble": "true"
        },
        {
          "field": "Group",
          "label": "Group",
          "type": "checkbox",
          "label in bubble": "true"
        },
        {
          "field": "Joint effect",
          "label": "Joint effect(>=)",
          "type": "search greater than",
          "label in bubble": "true"
        },
        {
          "field": "Marginal effect",
          "label": "Marginal effect(>=)",
          "type": "search greater than",
          "label in bubble": "true"
        }
      ],
      "visualizer": {
        "label": "20 most relevant human phenotypes",
        "legend": "20 most relevant human phenotypes",
        "type": "cfde xing",
        "render by": "Human phenotype",
        "threshold type": "highest n",
        "threshold": 20,
        "threshold field": "Fold-increase",
        "x axis field": "Probability",
        "suppliment field": "Fold-increase",
        "suppliment fields": [
          "Relative success score",
          "Fold-increase"
        ],
        "color by": "Background group",
        "dot colors": {
          "common": "#ff0000",
          "rare": "#3300ff"
        },
        "link to": "https://a2f.hugeamp.org/phenotype.html?phenotype=",
        "link field": "raw phenotype"
      }
    }
  ]
}

