}
.page-description-content h4 {
  font-size: 16px;
  font-weight: bold;
}
.page-description-content p {
  font-size: 14px;
  line-height: normal;
  margin: 0;
  margin-bottom: 8px;
}

/* filters, search blocks */
.multi-page-search-wrapper {
  height: fit-content;
}
div.filtering-ui-wrapper {
  border: 0;
  border-radius: 0;
